contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take a deposit amount, deposit it into c, then call withdrawAll and assert the invariant.
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient balance to fund deposit");

        // record c's balance before deposit
        uint cBalanceBefore = address(c).balance;

        // deposit into c as this contract
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // After deposit, the caller's recorded credit should have increased by depositAmount.
        // We can observe c's balance now.
        uint cBalanceAfterDeposit = address(c).balance;

        // Attempt withdrawAll and capture whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // record c's balance after withdraw attempt
        uint cBalanceAfterWithdraw = address(c).balance;

        // The only public observations we have are address(c).balance and the revert flag.
        // Let credited = cBalanceAfterDeposit - cBalanceBefore  (the amount we deposited and thus credited to this caller).
        // If withdrawAll did not revert, then c's balance must have decreased by at least credited (no new funds created).
        // Also, if withdraw succeeded, the caller's credit should be cleared; we express that by requiring that c's balance decreased by at least credited.
        // Avoid underflow by branching on cBalanceAfterDeposit >= cBalanceBefore.

        uint credited = 0;
        if (cBalanceAfterDeposit >= cBalanceBefore) {
            credited = cBalanceAfterDeposit - cBalanceBefore;
        }

        // Assert the general rule: if call didn't revert, c's balance after withdraw <= balance after deposit - credited
        // which is equivalent to cBalanceAfterWithdraw + credited <= cBalanceAfterDeposit
        assert(reverted || (cBalanceAfterWithdraw + credited <= cBalanceAfterDeposit));
    }

    receive() external payable {}
}

